// Prepare tenant data with yesterday's date
const tenants = Array.isArray($input.all()) ? $input.all() : [$input.item.json];
const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);
const yesterdayStr = yesterday.toISOString().split('T')[0];

return tenants.map(tenant => ({
  tenant_id: tenant.id,
  report_date: yesterdayStr,
  date_start: yesterdayStr + 'T00:00:00Z',
  date_end: yesterdayStr + 'T23:59:59Z'
}));

// Format daily report message
const summary = $('Get Daily Summary').first()?.json?.[0] || {};
const pendingOrders = $('Get Pending Orders').first()?.json || [];
const tenantConfig = $('Get Tenant Config').first()?.json?.[0] || {};
const tenantData = $('Prepare Tenant Data').first().json;

const revenue = summary.revenue || 0;
const orders = summary.order_count || 0;
const leads = summary.lead_count || 0;
const conversionRate = summary.conversion_rate || 0;
const pendingCount = pendingOrders.length;
const pendingAmount = pendingOrders.reduce((sum, o) => sum + parseFloat(o.total_amount || 0), 0);

const businessName = tenantConfig.business_name || 'Your Business';
const reportDate = new Date(tenantData.report_date).toLocaleDateString('en-KE', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const message = `📊 Daily Report for ${businessName}
──────────────────
📅 ${reportDate}

✅ Revenue: KSh ${revenue.toLocaleString('en-KE')}
✅ Orders: ${orders}
✅ New Leads: ${leads}
📈 Conversion: ${conversionRate.toFixed(1)}%

${pendingCount > 0 ? `⚠️ Pending: ${pendingCount} orders (KSh ${pendingAmount.toLocaleString('en-KE')})
` : ''}──────────────────
View details: [Dashboard Link]

Asante! 🎉`;

return {
  tenant_id: tenantData.tenant_id,
  owner_phone: tenantConfig.owner_phone,
  message: message,
  report_date: tenantData.report_date,
  metrics: {
    revenue: revenue,
    orders: orders,
    leads: leads,
    conversion_rate: conversionRate,
    pending_count: pendingCount,
    pending_amount: pendingAmount
  }
};

// Summary of daily reports sent
const allReports = $input.all();
const sent = allReports.filter(r => r.owner_phone).length;
const totalRevenue = allReports.reduce((sum, r) => sum + (r.metrics?.revenue || 0), 0);

return {
  reports_sent: sent,
  total_tenants: allReports.length,
  total_revenue_reported: totalRevenue,
  timestamp: new Date().toISOString()
};
